using DriveOS.Modules.Workforce.Domain.LeavePolicies; using DriveOS.SharedKernel.Identifiers; using Microsoft.EntityFrameworkCore;
namespace DriveOS.Modules.Workforce.Infrastructure.Persistence.Repositories;
internal sealed class LeavePolicyRepository(WorkforceDbContext db):ILeavePolicyRepository{public Task<LeavePolicy?> GetByIdAsync(OrganizationId o,LeavePolicyId id,CancellationToken ct=default)=>db.LeavePolicies.AsNoTracking().SingleOrDefaultAsync(x=>x.OrganizationId==o&&x.Id==id,ct);public Task<LeavePolicy?> GetByIdForUpdateAsync(OrganizationId o,LeavePolicyId id,CancellationToken ct=default)=>db.LeavePolicies.SingleOrDefaultAsync(x=>x.OrganizationId==o&&x.Id==id,ct);public Task<LeavePolicy?> FindByCodeAsync(OrganizationId o,string country,string code,CancellationToken ct=default){country=country.Trim().ToUpperInvariant();code=code.Trim().ToUpperInvariant();return db.LeavePolicies.AsNoTracking().SingleOrDefaultAsync(x=>x.OrganizationId==o&&x.CountryCode==country&&x.Code==code,ct);}public async Task<IReadOnlyList<LeavePolicy>> ListAsync(OrganizationId o,string? country,LeavePolicyStatus? status,CancellationToken ct=default){var q=db.LeavePolicies.AsNoTracking().Where(x=>x.OrganizationId==o);if(!string.IsNullOrWhiteSpace(country)){var c=country.Trim().ToUpperInvariant();q=q.Where(x=>x.CountryCode==c);}if(status.HasValue)q=q.Where(x=>x.Status==status.Value);return await q.OrderBy(x=>x.CountryCode).ThenBy(x=>x.Name).ToListAsync(ct);}public void Add(LeavePolicy p)=>db.LeavePolicies.Add(p);}
